<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Password reset</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body>@include('core._shell-start')<main class="ad-page st-page"><header class="ad-page-head"><div><p class="ad-eyebrow">Password reset</p><h1>Give these details to {{ $heading }}</h1><p>This is the only time the temporary password is shown.</p></div></header><section class="ad-cred" id="credential-panel"><dl class="ac-credentials"><div><dt>Username</dt><dd>{{ $user->username ?: $user->email }}</dd></div><div><dt>Temporary password</dt><dd><code data-secret>{{ $temporary_password }}</code></dd></div></dl></section><label class="ac-noted"><input type="checkbox" data-noted> I have noted or printed these details</label><a class="oak-btn oak-btn-primary is-disabled" data-done aria-disabled="true" href="{{ route('students.show',$student) }}">Done</a></main>@include('core._shell-end') @livewireScripts<script>const n=document.querySelector('[data-noted]'),d=document.querySelector('[data-done]'),s=document.querySelector('[data-secret]');n.addEventListener('change',()=>{d.setAttribute('aria-disabled',String(!n.checked));d.classList.toggle('is-disabled',!n.checked)});d.addEventListener('click',e=>{e.preventDefault();if(!n.checked)return;s.textContent='';window.location.replace(d.href)});window.addEventListener('pagehide',()=>s.textContent='')</script></body></html>
